// frontend/src/pages/TraderProfile.jsx

import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { fetchTraderById } from "../services/api";
import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS, CategoryScale, LinearScale,
  PointElement, LineElement, Title, Tooltip, Legend
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

export default function TraderProfile() {
  const { id } = useParams();
  const [data, setData] = useState(null);

  useEffect(() => {
    fetchTraderById(id).then(setData);
  }, [id]);

  if (!data) return <p>Loading...</p>;

  const { trader, trades, riskLogs, trustHistory } = data;

  const chartData = {
    labels: trustHistory.map((h) => new Date(h.recorded_at).toLocaleDateString()),
    datasets: [{
      label: "Trust Score Over Time",
      data: trustHistory.map((h) => h.trust_score),
      borderColor: "#38bdf8",
      backgroundColor: "rgba(56, 189, 248, 0.1)",
      tension: 0.4,
      fill: true
    }]
  };

  return (
    <div style={{ padding: "24px", background: "#0f172a", minHeight: "100vh", color: "#f1f5f9" }}>
      <h1>👤 {trader.trader_name}</h1>
      <p>Trust Score: <strong style={{ color: trader.trust_score < 50 ? "#ef4444" : "#22c55e" }}>
        {trader.trust_score}
      </strong></p>
      <p>Registered: {new Date(trader.registration_date).toLocaleDateString()}</p>

      {/* Trust History Chart */}
      {trustHistory.length > 0 && (
        <>
          <h2>📈 Trust Score History</h2>
          <div style={{ background: "#1e293b", padding: "16px", borderRadius: "10px", maxWidth: "700px" }}>
            <Line data={chartData} />
          </div>
        </>
      )}

      {/* Fraud Involvement */}
      <h2 style={{ marginTop: "24px" }}>🚨 Fraud Logs ({riskLogs.length})</h2>
      {riskLogs.map((log) => (
        <div key={log.risk_id} style={{ background: "#1e293b", padding: "12px", marginBottom: "8px", borderRadius: "8px" }}>
          <strong>Risk Score: {log.risk_score}</strong> — {log.reason}
        </div>
      ))}

      {/* Transactions */}
      <h2 style={{ marginTop: "24px" }}>📋 Recent Trades</h2>
      <table style={{ width: "100%", borderCollapse: "collapse" }}>
        <thead>
          <tr>
            <th>Trade ID</th><th>Stock</th><th>Buyer</th><th>Price</th><th>Qty</th><th>Time</th>
          </tr>
        </thead>
        <tbody>
          {trades.map((t) => (
            <tr key={t.trade_id} style={{ borderBottom: "1px solid #334155" }}>
              <td>{t.trade_id}</td>
              <td>{t.stock_id}</td>
              <td>{t.buyer_id}</td>
              <td>${t.price}</td>
              <td>{t.quantity}</td>
              <td>{new Date(t.timestamp).toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
